  data: {},
  currentYear: 2026,
  activeTab: "Overview",
  activeSubTab: "overview",
  lastActiveMonth: "Overview",
  lastBudgetsTab: "Budgets",
  lastAnalyticsTab: "Spend",
  globalEditMode: false,
  draggedItemInfo: null,
  activeChart: null,
  activeUser: 'Joint',
  unlockedUsers: {},
  isMasterUnlocked: false,
  unmaskedSalaries: {},
